    Ticket = apps.get_model('portal', 'Ticket')
    Work = apps.get_model('portal', 'AgentWork')
    for tenant in apps.get_model('portal', 'Tenant').objects.using(alias).all().iterator():
        if schema_editor.connection.vendor == 'postgresql':
            with schema_editor.connection.cursor() as cursor:
                cursor.execute("SELECT set_config('app.tenant_id', %s, true)", [str(tenant.pk)])
        for ticket in Ticket.objects.using(alias).filter(tenant=tenant).exclude(status__in=['resolved', 'closed', 'cancelled']).iterator():
            Work.objects.using(alias).get_or_create(ticket=ticket, defaults={
                'tenant_id': ticket.tenant_id, 'project_id': ticket.project_id, 'ticket_version': ticket.version})


